  F = rep(F, 'vec4 E=texture(uEb,uv),hy=texture(uHy,uv);float e=texture(uHt,uv).r,', 'vec4 E=bsp(uEb,uv),hy=texture(uHy,uv);float e=crs(uHt,uv).r,');
